// Regenerate the combined-event (M1.15) season fixtures for
// tests/combined-event.test.ts.
//
// Run from apps/web (also runs automatically as `pretest`):
//   node tests/fixtures/build-combined-event-season.mjs
//
// Output: tests/fixtures/combined-event-{1-opener,2-classic,3a,3b}.axdb
//         (gitignored — regenerated by `pnpm pretest`).
//
// The data is entirely synthetic — see feedback_sensitive_axdb_fixtures memory.
//
// Scenario (2027 synthetic season, classes C1 / CS):
//
//  Group 1 "Spring Opener"   (2027-03-01, single event)
//  Group 2 "Summer Classic"  (2027-04-01, single event)
//  Group 3 "Cone in 60 Seconds (A)" + "(B)" (2027-05-15, combined pair)
//
//  ⇒ 3 scoring groups. Dynamic qualifying threshold: floor(3/2)+1 = 2.
//
// Group 3 drivers (class, session A / session B times in ms; C1 unless noted):
//
//  Quinn Q  (CMB-001, C1) — also races groups 1+2. A=38000  B=50000  sum=88000
//  Rae R    (CMB-002, C1) — also races groups 1+2. A=50000  B=36000  sum=86000
//  Ivy Ingram (CMB-003, C1)                        A=41000  B=42000  sum=83000
//    — wins the class on SUM despite winning neither individual session
//      (X=Quinn wins A@38000, Y=Rae wins B@36000; Ivy's sum is still lowest).
//  Leo Lang   (CMB-004, C1)  A=43000, no B entry  → forfeit: missing session B
//  Mia Cole   (CMB-005, C1)  A=DNF,   B=45000     → forfeit: missing session A
//  Nick Diaz  (CMB-006)      A=C1 44000, B=CS 48000 → class mismatch, forfeits
//                              both C1 (missing B) and CS (missing A)
//  Owen Ortiz #62  (CMB-007, CS) — co-drive primary. A=55000  B=56000  sum=111000
//  Pia Ortiz  #162 (CMB-008, CS) — co-drive (number-suffix convention, PRD
//                                  BUILD.md "62" + "162" example). A=58000  B=57000  sum=115000
//
// Group 3 / C1 points: fastest sum = Ivy 83000 → 1000.
//   Quinn: round(1000*83000/88000) = 943
//   Rae:   round(1000*83000/86000) = 965
// Group 3 / CS points: fastest sum = Owen 111000 → 1000.
//   Pia:   round(1000*111000/115000) = 965
//
// Season totals (threshold 2 — top 2 of N scores count):
//   Quinn (C1): opener=1000, classic=1000, combined=943
//     → sorted desc [1000,1000,943], top-2 = 2000, combined dropped. eligible (3 scores ≥ 2).
//   Rae (C1): opener=962, classic=941, combined=965
//     → sorted desc [965,962,941], top-2 = 1927 (965+962), classic(941) dropped. eligible.
//   Ivy (C1): only the combined group → 1 score, 1000 pts, provisional 1/2.
//   Owen (CS): only the combined group → 1 score, 1000 pts, provisional 1/2.
//   Pia  (CS): only the combined group → 1 score, 965 pts, provisional 1/2.
//   Leo, Mia, Nick: zero scores (forfeited their only scoring group) — absent
//     from season standings entirely; covered instead by
//     buildCombinedResults()'s unranked-section assertions.
//
// Opener (2027-03-01) / C1: Quinn=50000 (wins, 1000); Rae=52000 → round(1000*50000/52000)=962
// Classic (2027-04-01) / C1: Quinn=48000 (wins, 1000); Rae=51000 → round(1000*48000/51000)=941

import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { buildEventAxdb } from "./axdb-builder.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const ts = (isoDate) => Math.floor(new Date(`${isoDate}T12:00:00Z`).getTime() / 1000);

const ALL_CLASSES = [
  { id: 1, name: "C1", paxed: false, pax: 1.0 },
  { id: 2, name: "CS", paxed: true, pax: 0.92 },
];

function write(filename, ...args) {
  const counts = buildEventAxdb(join(here, filename), ...args);
  console.log(`Wrote ${filename}`, counts);
}

// ─── Group 1: Spring Opener — 2027-03-01 ────────────────────────────────────
write(
  "combined-event-1-opener.axdb",
  "Spring Opener",
  "2027-03-01",
  ts("2027-03-01"),
  ALL_CLASSES,
  [
    { id: 1, last: "Quill", first: "Quinn", num: "201", classId: 1, paxId: 1, memberNum: "CMB-001" },
    { id: 2, last: "Reyes", first: "Rae", num: "202", classId: 1, paxId: 1, memberNum: "CMB-002" },
  ],
  [
    { driverId: 1, deltaMs: 50000, cones: 0 },
    { driverId: 2, deltaMs: 52000, cones: 0 },
  ],
);

// ─── Group 2: Summer Classic — 2027-04-01 ───────────────────────────────────
write(
  "combined-event-2-classic.axdb",
  "Summer Classic",
  "2027-04-01",
  ts("2027-04-01"),
  ALL_CLASSES,
  [
    { id: 1, last: "Quill", first: "Quinn", num: "201", classId: 1, paxId: 1, memberNum: "CMB-001" },
    { id: 2, last: "Reyes", first: "Rae", num: "202", classId: 1, paxId: 1, memberNum: "CMB-002" },
  ],
  [
    { driverId: 1, deltaMs: 48000, cones: 0 },
    { driverId: 2, deltaMs: 51000, cones: 0 },
  ],
);

// ─── Group 3, session A: Cone in 60 Seconds (A) — 2027-05-15 ───────────────
write(
  "combined-event-3a.axdb",
  "Cone in 60 Seconds (A)",
  "2027-05-15",
  ts("2027-05-15"),
  ALL_CLASSES,
  [
    { id: 1, last: "Quill", first: "Quinn", num: "201", classId: 1, paxId: 1, memberNum: "CMB-001" },
    { id: 2, last: "Reyes", first: "Rae", num: "202", classId: 1, paxId: 1, memberNum: "CMB-002" },
    { id: 3, last: "Ingram", first: "Ivy", num: "203", classId: 1, paxId: 1, memberNum: "CMB-003" },
    { id: 4, last: "Lang", first: "Leo", num: "204", classId: 1, paxId: 1, memberNum: "CMB-004" },
    { id: 5, last: "Cole", first: "Mia", num: "205", classId: 1, paxId: 1, memberNum: "CMB-005" },
    { id: 6, last: "Diaz", first: "Nick", num: "206", classId: 1, paxId: 1, memberNum: "CMB-006" },
    { id: 7, last: "Ortiz", first: "Owen", num: "62", classId: 2, paxId: 2, memberNum: "CMB-007" },
    { id: 8, last: "Ortiz", first: "Pia", num: "162", classId: 2, paxId: 2, memberNum: "CMB-008" }, // co-drive of #62 (number-suffix convention)
  ],
  [
    { driverId: 1, deltaMs: 38000, cones: 0 },
    { driverId: 2, deltaMs: 50000, cones: 0 },
    { driverId: 3, deltaMs: 41000, cones: 0 },
    { driverId: 4, deltaMs: 43000, cones: 0 },
    { driverId: 5, deltaMs: 70000, cones: 0, disposition: "DNF" }, // Mia DNFs session A
    { driverId: 6, deltaMs: 44000, cones: 0 },
    { driverId: 7, deltaMs: 55000, cones: 0 },
    { driverId: 8, deltaMs: 58000, cones: 0 },
  ],
);

// ─── Group 3, session B: Cone in 60 Seconds (B) — 2027-05-15 ───────────────
// Leo doesn't enter B (missing-session forfeit). Nick enters CS this time,
// not C1 (class-mismatch forfeit, both classes).
write(
  "combined-event-3b.axdb",
  "Cone in 60 Seconds (B)",
  "2027-05-15",
  ts("2027-05-15") + 3600,
  ALL_CLASSES,
  [
    { id: 1, last: "Quill", first: "Quinn", num: "201", classId: 1, paxId: 1, memberNum: "CMB-001" },
    { id: 2, last: "Reyes", first: "Rae", num: "202", classId: 1, paxId: 1, memberNum: "CMB-002" },
    { id: 3, last: "Ingram", first: "Ivy", num: "203", classId: 1, paxId: 1, memberNum: "CMB-003" },
    { id: 4, last: "Cole", first: "Mia", num: "205", classId: 1, paxId: 1, memberNum: "CMB-005" },
    { id: 5, last: "Diaz", first: "Nick", num: "206", classId: 2, paxId: 2, memberNum: "CMB-006" }, // CS this session — class mismatch vs. session A's C1
    { id: 6, last: "Ortiz", first: "Owen", num: "62", classId: 2, paxId: 2, memberNum: "CMB-007" },
    { id: 7, last: "Ortiz", first: "Pia", num: "162", classId: 2, paxId: 2, memberNum: "CMB-008" },
  ],
  [
    { driverId: 1, deltaMs: 50000, cones: 0 },
    { driverId: 2, deltaMs: 36000, cones: 0 },
    { driverId: 3, deltaMs: 42000, cones: 0 },
    { driverId: 4, deltaMs: 45000, cones: 0 },
    { driverId: 5, deltaMs: 48000, cones: 0 },
    { driverId: 6, deltaMs: 56000, cones: 0 },
    { driverId: 7, deltaMs: 57000, cones: 0 },
  ],
);

console.log("Done. Run `pnpm --filter web test` to verify.");
